#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE tmp = 0.0;
      #pragma omp simd reduction(+:tmp)
      for (j = 0; j < i; j++)
          tmp += L[i][j] * x[j];
      x[i] = (b[i] - tmp) / L[i][i];
    }
#pragma endscop

We do not change anything else.

Note: We are using the type DATA_TYPE for tmp. This is consistent.

Let's write the entire kernel_trisolv function with the optimized scop region.

We must not change anything outside the scop region.

So the entire kernel_trisolv function becomes:

static
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE tmp = 0.0;
      #pragma omp simd reduction(+:tmp)
      for (j = 0; j < i; j++)
          tmp += L[i][j] * x[j];
      x[i] = (b[i] - tmp) / L[i][i];
    }
#pragma endscop

}

We are done.
